INSERT INTO `jform_graphreport_head` VALUES ('402881885f3f9203015f44ee804402ba','SELECT \r\n    bs.store_code,\r\n    (select \r\n            sum(zui_da_tuo_Pan)\r\n        from\r\n            md_bin mb\r\n        where\r\n            mb.bin_store = bs.store_code\r\n                and mb.zui_da_tuo_Pan < 99999) as tuopansum,\r\n    (select \r\n            count(*)\r\n        from\r\n            wv_stock wv\r\n       where wv.bin_store  = bs.store_code ) as usecount\r\nfrom\r\n    ba_store bs\r\nhaving  tuopansum > 0','CWSYL','储位使用率','储位使用率','托盘','store_code','Y',''),('402881885f6d30c9015f6d5b38f40004','select  wc.cost_name,round(sum(wc.day_cost_hsj),2) as daycost from wm_day_cost wc group by  wc.cost_name having sum(wc.day_cost_hsj) <> 0','FYHZFX','费用名称','费用汇总分析','费用','cost_name','Y',''),('402881e64ca71152014ca71152480000','select a.userid, count(*) ct, sum(case when right(logcontent, 4) in (\'登录成功\', \'cess\') then 1 else 0 end) login_count from t_s_log a where {operatetime} group by a.userid order by ct desc','yhcztj','用户操作统计','用户操作统计','操作次数','userid','Y','function getTotalRows(totalRows) {\r\n    return [\'ct\', \'login_count\'];\r\n}'),('4028b8815e486236015e4870b7f30003','select	ws.shp_ming_cheng,sum(ws.goods_qua) as ct from wv_stock ws   group by ws.shp_ming_cheng \r\n order by ct desc limit 0,10','KCSLTOP10','库存数量TOP10','库存数量TOP10','数量','shp_ming_cheng','Y',''),('4028b8815e486236015e4879ee700010','select	ws.zhong_wen_qch,sum(ws.goods_qua) as ct from wv_stock ws   group by ws.zhong_wen_qch order by ct desc limit 0,10','khsltop10','客户数量TOP10','客户数量TOP10','数量','zhong_wen_qch','Y','');
