CREATE DEFINER=`root`@`localhost` PROCEDURE `update_wm_last_day_stock`(IN `wmdate` VARCHAR(45))
BEGIN

delete from wm_his_stock_data;


INSERT INTO wm_his_stock_data (
  `id` ,
  `his_date` ,
  `cus_code` ,
  `ku_wei_bian_ma` ,
  `bin_id` ,
  `goods_id` ,
  `count` ,
  `base_unit`,
	`pro_data`
)
SELECT
    concat(mdp.id,wmdate,
            mdp.cus_code,
            mdp.ku_wei_bian_ma,
            mdp.bin_id,
            mdp.goods_id,mdp.goods_pro_data) as id,
    wmdate as his_date,
    mdp.cus_code,
    mdp.ku_wei_bian_ma,
    mdp.bin_id,
    mdp.goods_id,
    sum(base_goodscount) as count,
    mdp.base_unit,
goods_pro_data

FROM
    mv_down_and_up mdp
where
    (mdp.leixing = 'S'
        and to_days(mdp.create_date) <= to_days(wmdate))
        or (mdp.leixing = 'H'
        and to_days(mdp.create_date) <= to_days(wmdate))

group by mdp.cus_code , mdp.ku_wei_bian_ma , mdp.bin_id,mdp.goods_id,mdp.goods_pro_data
having sum(base_goodscount) <> 0 and id is not null
order by cus_code , create_date;
END ;;
